excels.excel:

EXPORT WITH SHEET="供应商供货台账", HEADER=true,
    MAPPING={"a":"供应商","b":"采购单号","c":"物料名称","d":"供货数量","e":"单价","f":"供货金额","g":"到货状态"},
    FORMAT={"d":"#,##0","e":"#,##0.00","f":"#,##0.00"},
    FORMULAS={
        F2:'D2*E2',F3:'D3*E3',
        F4:'SUM(F2:F3)',
        F5:'D5*E5',F6:'D6*E6',F7:'D7*E7',
        F8:'SUM(F5:F7)',
        F9:'D9*E9',F10:'D10*E10',
        F11:'SUM(F9:F10)',
        F12:'F4+F8+F11'
    },
    STYLE={
        ROW 4:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 11:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 12:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    },
    MERGE:{
        RANGE A2:A3 WITH MERGE_WITH_FIRST,
        RANGE A5:A7 WITH MERGE_WITH_FIRST,
        RANGE A9:A10 WITH MERGE_WITH_FIRST
    }
